  const seen = new Set(), contacts = [], rejected = []; let duplicates = 0;
  rows.forEach((raw, i) => {
    try {
      if (!raw || typeof raw !== 'object' || Array.isArray(raw)) throw new Error('Invalid contact');
      const row = Object.fromEntries(Object.entries(raw).map(([k,v])=>[k.replace(/^\uFEFF/,'').trim().toLowerCase().replace(/\s+/g,'_'),v]));
      const c = {};
      for (const k of fields) c[k] = k === 'phone' ? phone(row[k], options) : clean(row[k], k === 'email' ? 254 : 200);
