check('International phone',()=>phone('+1 (202) 555-0101')==='+12025550101');
check('00 international prefix',()=>phone('0044 7700 900123')==='+447700900123');
check('Explicit national convention',()=>phone('0300 1234567',{defaultCallingCode:'92',trunkPrefix:'0'})==='+923001234567');
